import java.util.*;

public class Main {
    static class Node {
        int value;
        Node next;
        Node(int value) { this.value = value; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt(), k = sc.nextInt();
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(sc.nextInt());
            if (i > 0) nodes[i - 1].next = nodes[i];
        }
        if (k >= 0) nodes[n - 1].next = nodes[k];
        Node slow = nodes[0], fast = nodes[0];
        boolean cycle = false;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow == fast) { cycle = true; break; }
        }
        System.out.println(cycle ? "Cycle" : "No cycle");
    }
}

